struct anim_control_t {};
struct vector3d {
  float x, y, z;
  vector3d operator-(const vector3d&) const;
};
struct quaternion {
  float x, y, z, w;
  quaternion get_conjugate() const;
  quaternion operator*(const quaternion&) const;
  quaternion& operator=(const quaternion&);
  void to_matrix(void*) const;
};
struct vector4d { float x, y, z, w; } __attribute__((aligned(16)));
struct matrix4x4 { vector4d x, y, z, w; };
class po {
  matrix4x4 m;
public:
  const vector3d& get_position() const;
  quaternion get_quaternion() const;
  float get_scale() const;
};
template<class T> class anim {
protected:
  unsigned short flags;
public:
  virtual void set_flag(int);
  virtual void clear_flag(int);
  virtual void set_flag(int, bool);
  virtual void set_time(float);
  virtual void frame_advance(const anim_control_t&, T*);
  virtual void get_value(const anim_control_t&, T*) const;
  virtual void get_value(float, T*) const;
  bool is_valid() const { return flags & 0x1000; }
};
inline vector3d anim_xform3d_1(const vector3d *rot, const vector3d &sv)
{
  vector3d res;
  res.x = rot[0].x * sv.x + rot[1].x * sv.y + rot[2].x * sv.z;
  res.y = rot[0].y * sv.x + rot[1].y * sv.y + rot[2].y * sv.z;
  res.z = rot[0].z * sv.x + rot[1].z * sv.y + rot[2].z * sv.z;
  return(res);
}
inline void anim_create_rot_vectors(vector3d *mat, const quaternion &q)
{
  matrix4x4 rot_mat;
  q.to_matrix( &rot_mat );
  mat[0].x = rot_mat.x.x;
  mat[0].y = rot_mat.x.y;
  mat[0].z = rot_mat.x.z;
  mat[1].x = rot_mat.y.x;
  mat[1].y = rot_mat.y.y;
  mat[1].z = rot_mat.y.z;
  mat[2].x = rot_mat.z.x;
  mat[2].y = rot_mat.z.y;
  mat[2].z = rot_mat.z.z;
}
class po_anim: public anim<po> {
  anim<vector3d>* P;
  anim<quaternion>* R;
  anim<float>* S;
  vector3d P_start;
  quaternion R_start;
  float S_start;
  vector3d R_start_mat[3];
public:
  bool has_P() const { return P && P->is_valid(); }
  bool has_R() const { return R && R->is_valid(); }
  bool has_S() const { return S && S->is_valid(); }
  bool is_relative_to_start() const { return flags & 0x20; }
  void reset_start(const anim_control_t&, const po&);
};
void po_anim::reset_start( const anim_control_t& ac, const po& dest )
{
  float Sd = dest.get_scale();
  if ( has_S() )
  {
    float s;
    S->get_value( ac, &s );
    S_start = Sd / s;
  }
  else
    S_start = Sd;
  quaternion Rd = dest.get_quaternion();
  if ( has_R() )
  {
    quaternion r;
    R->get_value( ac, &r );
    R_start = r.get_conjugate() * Rd;
  }
  else
    R_start = Rd;

  anim_create_rot_vectors(&R_start_mat[0], R_start);

  vector3d Pd = dest.get_position();
  if ( has_P() )
  {
    vector3d p;
    P->get_value( ac, &p );
    p = anim_xform3d_1(&R_start_mat[0], p);
    P_start = Pd - p;
  }
  else
    P_start = Pd;
}
